WITH valid_suppliers AS (SELECT * FROM suppliers WHERE rating <= 3.8 AND country NOT IN ('TH', 'JP')), city_summary AS (SELECT city, CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(rating) AS total_rating FROM valid_suppliers GROUP BY city, CASE WHEN rating >= 3.4 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END) SELECT city, rating_bucket, total_rating FROM city_summary WHERE total_rating >= 11;
